import urllib.request,urllib.error,json
class R:
    def __init__(s,c,t,h): s.status_code=c;s.text=t;s.headers=h
    def json(s): return json.loads(s.text)
def _do(m,u,headers=None):
    q=urllib.request.Request(u,method=m,headers=headers or {})
    try:
        x=urllib.request.urlopen(q);return R(x.status,x.read().decode(),x.headers)
    except urllib.error.HTTPError as e:
        return R(e.code,e.read().decode(),e.headers)
def get(u,headers=None): return _do("GET",u,headers)
def post(u): return _do("POST",u)
